// Lists engine plugins that are enabled by default, with their plugin dependencies.
// Usage: node list_plugins.js <EngineDir> <out.json>
const fs = require('fs');
const path = require('path');
const engineDir = process.argv[2];
const out = process.argv[3];
const root = path.join(engineDir, 'Engine', 'Plugins');
const found = [];
function walk(dir, depth) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  const up = entries.find(e => e.isFile() && e.name.endsWith('.uplugin'));
  if (up) { found.push(path.join(dir, up.name)); return; }
  if (depth > 6) return;
  for (const e of entries) if (e.isDirectory()) walk(path.join(dir, e.name), depth + 1);
}
walk(root, 0);
const plugins = {};
for (const f of found) {
  let j;
  try { j = JSON.parse(fs.readFileSync(f, 'utf8').replace(/^﻿/, '')); } catch (e) { continue; }
  const name = path.basename(f, '.uplugin');
  plugins[name] = {
    rel: path.relative(root, f).split(path.sep).join('/'),
    enabledByDefault: j.EnabledByDefault === true,
    deps: (j.Plugins || []).filter(p => p.Enabled !== false && !p.Optional).map(p => p.Name),
    optDeps: (j.Plugins || []).filter(p => p.Enabled !== false && p.Optional).map(p => p.Name),
    modules: (j.Modules || []).length,
    category: j.Category || '',
  };
}
fs.writeFileSync(out, JSON.stringify(plugins, null, 1));
const def = Object.entries(plugins).filter(([, p]) => p.enabledByDefault);
console.log('total plugins', Object.keys(plugins).length, 'enabledByDefault', def.length);
for (const [n, p] of def.sort((a, b) => a[1].rel.localeCompare(b[1].rel))) console.log(p.rel.replace(/\/[^/]+$/, ''), '|', p.modules);

