	UPROPERTY() TObjectPtr<UInputAction> FaceUp;
	UPROPERTY() TObjectPtr<UInputAction> FaceLeft;
	UPROPERTY() TObjectPtr<UInputAction> FaceDown;
	UPROPERTY() TObjectPtr<UInputAction> FaceRight;
